"use client"

import { Auth01 } from "@/registry/blocks/auth-01/auth-01"

/**
 * 登录页入口：把下面几个回调换成你自己的认证实现。
 * 回调返回 Promise；失败时 throw new Error("中文原因")，组件会显示在表单上方。
 * 登录成功后的跳转请在 onSignIn / onSocialSignIn 里自行处理，例如 router.push("/")。
 */
export default function LoginPage() {
  return (
    <Auth01
      brand={{ name: "Acme" }}
      onSignIn={async (values) => {
        // TODO: 调用你的认证服务，例如 authClient.signIn.email(...)
        console.info("sign in", values)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onSignUp={async (values) => {
        console.info("sign up", values)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onForgotPassword={async (email) => {
        console.info("forgot password", email)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onSendCode={async (phone) => {
        console.info("send code", phone)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
      onSocialSignIn={async (provider) => {
        console.info("social sign in", provider)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
    />
  )
}

"use client"

import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { useState } from "react"

import { cn } from "@/lib/utils"

import { defaultBrand, type BrandConfig } from "./brand"
import { BrandPanel, MobileBrand } from "./brand-panel"
import { ForgotPasswordForm } from "./forgot-password-form"
import { SignInForm, type SignInValues } from "./sign-in-form"
import { SignUpForm, type SignUpValues } from "./sign-up-form"
import type { SocialProvider } from "./social-buttons"

export type { BrandConfig, BrandFeature } from "./brand"
export type { SignInValues } from "./sign-in-form"
export type { SignUpValues } from "./sign-up-form"
export type { SocialProvider } from "./social-buttons"
export type AuthView = "sign-in" | "sign-up" | "forgot-password"

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))
// 未传回调时的示例实现：只在控制台打印，并模拟 0.8 秒的网络请求
const demo =
  <Args extends unknown[]>(name: string) =>
  async (...args: Args) => {
    console.info(`[auth-01] ${name}`, ...args)
    await wait(800)
  }

/**
 * 分屏式登录 / 注册页：左侧品牌面板 + 右侧表单，窄屏只显示表单。
 * 回调返回 Promise；组件管理 loading，回调 throw 的 Error.message 会显示为表单错误。
 */
export function Auth01({
  brand,
  defaultView = "sign-in",
  socialProviders = ["github", "google"],
  allowSignUp = true,
  termsHref = "#",
  privacyHref = "#",
  onSignIn = demo<[SignInValues]>("onSignIn"),
  onSignUp = demo<[SignUpValues]>("onSignUp"),
  onForgotPassword = demo<[string]>("onForgotPassword"),
  onSendCode = demo<[string]>("onSendCode"),
  onSocialSignIn = demo<[SocialProvider]>("onSocialSignIn"),
  className,
}: {
  /** 品牌信息，逐项覆盖默认的示例品牌 */
  brand?: Partial<BrandConfig>
  defaultView?: AuthView
  /** 启用的第三方登录，传空数组隐藏该区域 */
  socialProviders?: readonly SocialProvider[]
  /** 设为 false 隐藏「注册」入口（仅邀请制的产品） */
  allowSignUp?: boolean
  termsHref?: string
  privacyHref?: string
  onSignIn?: (values: SignInValues) => Promise<void>
  onSignUp?: (values: SignUpValues) => Promise<void>
  onForgotPassword?: (email: string) => Promise<void>
  onSendCode?: (phone: string) => Promise<void>
  onSocialSignIn?: (provider: SocialProvider) => Promise<void>
  className?: string
}) {
  const [view, setView] = useState<AuthView>(defaultView)
  const reducedMotion = useReducedMotion()
  const resolved: BrandConfig = { ...defaultBrand, ...brand }
  return (
    <div className={cn("relative flex min-h-svh", className)}>
      <BrandPanel brand={resolved} />
      <main className="relative flex flex-1 items-center justify-center bg-background p-6 pb-16 sm:p-12 sm:pb-16">
        <div className="w-full max-w-md">
          <MobileBrand brand={resolved} />
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={view}
              initial={{ opacity: 0, y: reducedMotion ? 0 : 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: reducedMotion ? 0 : -8 }}
              transition={{ duration: 0.18 }}
            >
              {view === "sign-in" && (
                <SignInForm
                  socialProviders={socialProviders}
                  allowSignUp={allowSignUp}
                  onSignIn={onSignIn}
                  onSendCode={onSendCode}
                  onSocialSignIn={onSocialSignIn}
                  onForgotPassword={() => setView("forgot-password")}
                  onSwitchToSignUp={() => setView("sign-up")}
                />
              )}
              {view === "sign-up" && (
                <SignUpForm
                  termsHref={termsHref}
                  privacyHref={privacyHref}
                  onSignUp={onSignUp}
                  onSwitchToSignIn={() => setView("sign-in")}
                />
              )}
              {view === "forgot-password" && (
                <ForgotPasswordForm
                  onForgotPassword={onForgotPassword}
                  onSwitchToSignIn={() => setView("sign-in")}
                />
              )}
            </motion.div>
          </AnimatePresence>
        </div>
        <p className="absolute right-6 bottom-4 text-xs text-muted-foreground">
          {resolved.copyright}
        </p>
      </main>
    </div>
  )
}

import { Gauge, Hexagon, ShieldCheck, Zap } from "lucide-react"
import type { ReactNode } from "react"

export type BrandFeature = {
  icon: ReactNode
  title: string
  description: string
}

export type BrandConfig = {
  /** 产品名，显示在 Logo 旁 */
  name: string
  /** Logo 节点：建议用 currentColor 的 SVG，这样在品牌面板（反色）和表单上方（正常色）都能看清 */
  logo: ReactNode
  /** 品牌面板的大标题 */
  title: string
  description: string
  /** 品牌面板上的特性列表，建议 2–3 条 */
  features: BrandFeature[]
  /** 右下角的版权文字 */
  copyright: string
}

/** 示例品牌：换成自己的产品信息，或通过 Auth01 的 brand 属性逐项覆盖。 */
export const defaultBrand: BrandConfig = {
  name: "Acme",
  logo: <Hexagon strokeWidth={1.5} />,
  title: "把想法变成可用的产品",
  description: "一个账号，打开全部工具。登录后继续上次的工作，随时随地保持同步。",
  features: [
    {
      icon: <Zap />,
      title: "快速上手",
      description: "几分钟完成配置，立刻开始使用",
    },
    {
      icon: <Gauge />,
      title: "稳定可靠",
      description: "全天候运行，关键数据实时同步",
    },
    {
      icon: <ShieldCheck />,
      title: "安全优先",
      description: "加密传输，权限精细可控",
    },
  ],
  copyright: "© 2026 Acme. 保留所有权利。",
}

import type { BrandConfig } from "./brand"

function Logo({ logo, className }: { logo: BrandConfig["logo"]; className: string }) {
  // 外层限定尺寸，内部的 svg / img 自动缩放到框内
  return (
    <span
      aria-hidden="true"
      className={`flex shrink-0 items-center justify-center [&>*]:max-h-full [&>*]:max-w-full [&>svg]:size-full ${className}`}
    >
      {logo}
    </span>
  )
}

/** 大屏左半边的品牌面板：主色渐变 + 模糊光斑 + 同心圆环。所有颜色都来自 primary。 */
export function BrandPanel({ brand }: { brand: BrandConfig }) {
  return (
    <aside
      aria-label={`${brand.name} 品牌介绍`}
      className="relative hidden overflow-hidden bg-linear-to-br from-primary/90 via-primary to-primary/80 text-primary-foreground lg:flex lg:w-1/2"
    >
      <div aria-hidden="true" className="absolute inset-0">
        <div className="absolute top-20 left-10 size-72 rounded-full bg-primary-foreground/10 blur-3xl" />
        <div className="absolute right-10 bottom-20 size-96 rounded-full bg-primary-foreground/5 blur-3xl" />
        <div className="absolute top-1/2 left-1/2 size-[600px] -translate-x-1/2 -translate-y-1/2 rounded-full border border-primary-foreground/10" />
        <div className="absolute top-1/2 left-1/2 size-[400px] -translate-x-1/2 -translate-y-1/2 rounded-full border border-primary-foreground/10" />
      </div>
      <div className="relative z-10 flex flex-col justify-center px-12 xl:px-20">
        <div className="mb-8 flex items-center gap-3">
          <Logo logo={brand.logo} className="size-14" />
          <span className="text-2xl font-bold" translate="no">
            {brand.name}
          </span>
        </div>
        <p className="mb-6 text-2xl leading-tight font-bold text-balance xl:text-3xl">
          {brand.title}
        </p>
        <p className="mb-10 max-w-md text-lg leading-8 text-primary-foreground/80">
          {brand.description}
        </p>
        <ul className="flex flex-col gap-4">
          {brand.features.map((feature) => (
            <li key={feature.title} className="flex items-center gap-4">
              <span
                aria-hidden="true"
                className="rounded-lg bg-primary-foreground/20 p-2 [&_svg]:size-5"
              >
                {feature.icon}
              </span>
              <div>
                <div className="font-medium">{feature.title}</div>
                <div className="text-sm text-primary-foreground/70">
                  {feature.description}
                </div>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </aside>
  )
}

/** 窄屏下表单上方的 Logo + 名称（品牌面板此时被隐藏）。 */
export function MobileBrand({ brand }: { brand: BrandConfig }) {
  return (
    <div className="mb-8 flex items-center justify-center gap-2 lg:hidden">
      <Logo logo={brand.logo} className="size-10" />
      <span className="text-xl font-bold" translate="no">
        {brand.name}
      </span>
    </div>
  )
}

"use client"

import { KeyRound, Lock, Smartphone, User } from "lucide-react"
import { useEffect, useState } from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Label } from "@/components/ui/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"

import {
  FormError,
  LinkButton,
  PasswordField,
  SubmitButton,
  TextField,
  ViewHeading,
} from "./form-parts"
import { codeSignInSchema, signInSchema } from "./schemas"
import { SocialButtons, type SocialProvider } from "./social-buttons"
import { useAsyncAction, useAuthForm } from "./use-auth-form"

export type SignInValues =
  | { method: "password"; account: string; password: string; remember: boolean }
  | { method: "code"; phone: string; code: string }

const CODE_COOLDOWN = 60

function PasswordSignIn({
  onSignIn,
  onForgotPassword,
}: {
  onSignIn: (values: SignInValues) => Promise<void>
  onForgotPassword: () => void
}) {
  const form = useAuthForm(signInSchema, {
    account: "",
    password: "",
    remember: false,
  })
  return (
    <form
      noValidate
      onSubmit={form.handleSubmit((values) =>
        onSignIn({ method: "password", ...values }),
      )}
      className="flex flex-col gap-5"
    >
      <FormError message={form.formError} />
      <TextField
        id="sign-in-account"
        label="用户名或邮箱"
        icon={User}
        autoComplete="username"
        placeholder="请输入用户名或邮箱"
        value={form.values.account}
        error={form.errors.account}
        onChange={(event) => form.setValue("account", event.target.value)}
        onBlur={() => form.blur("account")}
      />
      <PasswordField
        id="sign-in-password"
        label="密码"
        icon={Lock}
        autoComplete="current-password"
        placeholder="请输入密码"
        value={form.values.password}
        error={form.errors.password}
        onChange={(event) => form.setValue("password", event.target.value)}
        onBlur={() => form.blur("password")}
        labelAction={
          <LinkButton className="text-xs" onClick={onForgotPassword}>
            忘记密码？
          </LinkButton>
        }
      />
      <div className="flex items-center gap-2">
        <Checkbox
          id="sign-in-remember"
          checked={form.values.remember}
          onCheckedChange={(checked) => form.setValue("remember", checked === true)}
        />
        <Label htmlFor="sign-in-remember" className="cursor-pointer font-normal">
          记住登录状态
        </Label>
      </div>
      <SubmitButton pending={form.pending} pendingText="登录中…">
        登录
      </SubmitButton>
    </form>
  )
}

function CodeSignIn({
  onSignIn,
  onSendCode,
}: {
  onSignIn: (values: SignInValues) => Promise<void>
  onSendCode: (phone: string) => Promise<void>
}) {
  const form = useAuthForm(codeSignInSchema, { phone: "", code: "" })
  const sender = useAsyncAction()
  const [seconds, setSeconds] = useState(0)
  useEffect(() => {
    if (seconds <= 0) return
    const timer = window.setTimeout(() => setSeconds((value) => value - 1), 1000)
    return () => window.clearTimeout(timer)
  }, [seconds])

  const sendCode = async () => {
    if (!form.validateField("phone")) return
    const sent = await sender.run(() => onSendCode(form.values.phone.trim()))
    if (sent) setSeconds(CODE_COOLDOWN)
  }
  return (
    <form
      noValidate
      onSubmit={form.handleSubmit((values) =>
        onSignIn({ method: "code", ...values }),
      )}
      className="flex flex-col gap-5"
    >
      <FormError message={form.formError ?? sender.error} />
      <TextField
        id="sign-in-phone"
        label="手机号"
        icon={Smartphone}
        type="tel"
        inputMode="numeric"
        autoComplete="tel"
        placeholder="请输入 11 位手机号"
        value={form.values.phone}
        error={form.errors.phone}
        onChange={(event) => form.setValue("phone", event.target.value)}
        onBlur={() => form.blur("phone")}
      />
      <TextField
        id="sign-in-code"
        label="验证码"
        icon={KeyRound}
        inputMode="numeric"
        maxLength={6}
        autoComplete="one-time-code"
        placeholder="6 位数字验证码"
        value={form.values.code}
        error={form.errors.code}
        onChange={(event) => form.setValue("code", event.target.value)}
        onBlur={() => form.blur("code")}
        adjacent={
          <Button
            type="button"
            variant="outline"
            className="h-10 w-28 shrink-0 tabular-nums"
            disabled={sender.pending || seconds > 0}
            onClick={sendCode}
          >
            {sender.pending
              ? "发送中…"
              : seconds > 0
                ? `${seconds}s 后重发`
                : "获取验证码"}
          </Button>
        }
      />
      <SubmitButton pending={form.pending} pendingText="登录中…">
        登录
      </SubmitButton>
    </form>
  )
}

export function SignInForm({
  socialProviders,
  allowSignUp,
  onSignIn,
  onSendCode,
  onSocialSignIn,
  onForgotPassword,
  onSwitchToSignUp,
}: {
  socialProviders: readonly SocialProvider[]
  allowSignUp: boolean
  onSignIn: (values: SignInValues) => Promise<void>
  onSendCode: (phone: string) => Promise<void>
  onSocialSignIn: (provider: SocialProvider) => Promise<void>
  onForgotPassword: () => void
  onSwitchToSignUp: () => void
}) {
  const [method, setMethod] = useState("password")
  const social = useAsyncAction()
  return (
    <div className="flex flex-col gap-5">
      <ViewHeading title="欢迎回来" description="请输入您的账号信息登录" />
      <Tabs value={method} onValueChange={(value) => setMethod(String(value))}>
        <TabsList aria-label="登录方式" className="w-full">
          <TabsTrigger value="password">密码登录</TabsTrigger>
          <TabsTrigger value="code">验证码登录</TabsTrigger>
        </TabsList>
        <TabsContent value="password" className="pt-3">
          <PasswordSignIn
            onSignIn={onSignIn}
            onForgotPassword={onForgotPassword}
          />
        </TabsContent>
        <TabsContent value="code" className="pt-3">
          <CodeSignIn onSignIn={onSignIn} onSendCode={onSendCode} />
        </TabsContent>
      </Tabs>
      {socialProviders.length > 0 && (
        <>
          <div
            role="separator"
            className="flex items-center gap-3 text-xs text-muted-foreground before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border"
          >
            或
          </div>
          <FormError message={social.error} />
          <SocialButtons
            providers={socialProviders}
            pending={social.pending}
            onSelect={(provider) =>
              social.run(() => onSocialSignIn(provider))
            }
          />
        </>
      )}
      {allowSignUp && (
        <p className="text-center text-sm text-muted-foreground">
          还没有账号？{" "}
          <LinkButton onClick={onSwitchToSignUp}>注册</LinkButton>
        </p>
      )}
    </div>
  )
}

"use client"

import { Lock, Mail, User } from "lucide-react"

import { Checkbox } from "@/components/ui/checkbox"
import { Label } from "@/components/ui/label"

import {
  FormError,
  LinkButton,
  PasswordField,
  SubmitButton,
  TextField,
  ViewHeading,
} from "./form-parts"
import { PasswordStrength } from "./password-strength"
import { signUpSchema } from "./schemas"
import { useAuthForm } from "./use-auth-form"

export type SignUpValues = { name: string; email: string; password: string }

export function SignUpForm({
  termsHref,
  privacyHref,
  onSignUp,
  onSwitchToSignIn,
}: {
  termsHref: string
  privacyHref: string
  onSignUp: (values: SignUpValues) => Promise<void>
  onSwitchToSignIn: () => void
}) {
  const form = useAuthForm(signUpSchema, {
    name: "",
    email: "",
    password: "",
    confirm: "",
    terms: false,
  })
  return (
    <div className="flex flex-col gap-5">
      <ViewHeading title="创建账号" description="填写以下信息，几步完成注册" />
      <form
        noValidate
        onSubmit={form.handleSubmit(({ name, email, password }) =>
          onSignUp({ name: name.trim(), email: email.trim(), password }),
        )}
        className="flex flex-col gap-4"
      >
        <FormError message={form.formError} />
        <TextField
          id="sign-up-name"
          label="姓名"
          icon={User}
          autoComplete="name"
          placeholder="请输入姓名"
          value={form.values.name}
          error={form.errors.name}
          onChange={(event) => form.setValue("name", event.target.value)}
          onBlur={() => form.blur("name")}
        />
        <TextField
          id="sign-up-email"
          label="邮箱"
          icon={Mail}
          type="email"
          autoComplete="email"
          placeholder="name@example.com"
          value={form.values.email}
          error={form.errors.email}
          onChange={(event) => form.setValue("email", event.target.value)}
          onBlur={() => form.blur("email")}
        />
        <div className="flex flex-col gap-2">
          <PasswordField
            id="sign-up-password"
            label="密码"
            icon={Lock}
            autoComplete="new-password"
            placeholder="至少 8 位，包含字母和数字"
            value={form.values.password}
            error={form.errors.password}
            onChange={(event) => form.setValue("password", event.target.value)}
            onBlur={() => form.blur("password")}
          />
          <PasswordStrength password={form.values.password} />
        </div>
        <PasswordField
          id="sign-up-confirm"
          label="确认密码"
          icon={Lock}
          autoComplete="new-password"
          placeholder="再次输入密码"
          value={form.values.confirm}
          error={form.errors.confirm}
          onChange={(event) => form.setValue("confirm", event.target.value)}
          onBlur={() => form.blur("confirm")}
        />
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-2">
            <Checkbox
              id="sign-up-terms"
              checked={form.values.terms}
              aria-invalid={form.errors.terms ? true : undefined}
              aria-describedby={form.errors.terms ? "sign-up-terms-error" : undefined}
              onCheckedChange={(checked) => form.setValue("terms", checked === true)}
            />
            <Label
              htmlFor="sign-up-terms"
              className="cursor-pointer leading-5 font-normal"
            >
              我已阅读并同意
              <a href={termsHref} className="text-primary underline-offset-4 hover:underline">
                服务条款
              </a>
              和
              <a href={privacyHref} className="text-primary underline-offset-4 hover:underline">
                隐私政策
              </a>
            </Label>
          </div>
          {form.errors.terms ? (
            <p id="sign-up-terms-error" className="text-xs text-destructive">
              {form.errors.terms}
            </p>
          ) : null}
        </div>
        <SubmitButton pending={form.pending} pendingText="注册中…">
          注册
        </SubmitButton>
      </form>
      <p className="text-center text-sm text-muted-foreground">
        已有账号？ <LinkButton onClick={onSwitchToSignIn}>登录</LinkButton>
      </p>
    </div>
  )
}

"use client"

import { Mail, MailCheck } from "lucide-react"
import { useState } from "react"

import { Button } from "@/components/ui/button"

import {
  FormError,
  SubmitButton,
  TextField,
  ViewHeading,
} from "./form-parts"
import { forgotPasswordSchema } from "./schemas"
import { useAuthForm } from "./use-auth-form"

export function ForgotPasswordForm({
  onForgotPassword,
  onSwitchToSignIn,
}: {
  onForgotPassword: (email: string) => Promise<void>
  onSwitchToSignIn: () => void
}) {
  const form = useAuthForm(forgotPasswordSchema, { email: "" })
  const [sentTo, setSentTo] = useState<string | null>(null)

  if (sentTo) {
    return (
      <div className="flex flex-col items-center gap-4 text-center" role="status">
        <span
          aria-hidden="true"
          className="flex size-14 items-center justify-center rounded-full bg-primary/10 text-primary [&_svg]:size-7"
        >
          <MailCheck />
        </span>
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-bold tracking-tight">邮件已发送</h1>
          <p className="text-sm leading-6 text-muted-foreground">
            我们已向 <span className="font-medium text-foreground">{sentTo}</span>{" "}
            发送了重置密码的链接，请查收邮件。没收到？请检查垃圾邮件箱。
          </p>
        </div>
        <Button className="h-10 w-full" onClick={onSwitchToSignIn}>
          返回登录
        </Button>
      </div>
    )
  }
  return (
    <div className="flex flex-col gap-5">
      <ViewHeading
        title="找回密码"
        description="输入注册时使用的邮箱，我们会发送重置链接"
      />
      <form
        noValidate
        onSubmit={form.handleSubmit(async ({ email }) => {
          await onForgotPassword(email.trim())
          setSentTo(email.trim())
        })}
        className="flex flex-col gap-5"
      >
        <FormError message={form.formError} />
        <TextField
          id="forgot-email"
          label="邮箱"
          icon={Mail}
          type="email"
          autoComplete="email"
          placeholder="name@example.com"
          value={form.values.email}
          error={form.errors.email}
          onChange={(event) => form.setValue("email", event.target.value)}
          onBlur={() => form.blur("email")}
        />
        <SubmitButton pending={form.pending} pendingText="发送中…">
          发送重置链接
        </SubmitButton>
      </form>
      <Button variant="ghost" className="h-10" onClick={onSwitchToSignIn}>
        返回登录
      </Button>
    </div>
  )
}

